-- SUPABASE USER IMPORT SCRIPT
-- This script securely imports all your WordPress users directly into Supabase Auth.

ON CONFLICT DO NOTHING;

SELECT gen_random_uuid(), id::text, id, format('{"sub":"%s","email":"%s"}', id::text, email)::jsonb, 'email', created_at, created_at, updated_at
FROM auth.users
WHERE NOT EXISTS (SELECT 1 FROM auth.identities WHERE user_id = auth.users.id);
